package com.gamehub.application.service; import com.gamehub.application.OperationsService; import java.util.List; public final class MembershipService { private final OperationsService ops; public MembershipService(OperationsService ops){this.ops=ops;} public List<String> plans()throws Exception{return ops.membershipPlans();} public String status(long c)throws Exception{return ops.membership(c);} public long subscribe(long c,String plan)throws Exception{return ops.subscribeOrRenew(c,plan);} }